<script setup lang="ts">
// a sheet you already have: fill in the blank, or hand over the file
import { ref } from 'vue'
import { toast } from '../session'
import { keep, mine, choose } from '../heroes'
import { saveMap } from '../core/store'
import { blankPaper, fromFields, fromJson, fromText, settle, toPaper, type Bring } from '../rules/paper'
import { sanitize, type Hero } from '../rules/hero'
import Bar from './Bar.vue'
import Record from './Record.vue'
const p = defineProps<{ edit?: Hero | null; start?: 'blank' | '' }>(); const emit = defineEmits<{ done: [id: string] }>(); const clone = <T>(x: T): T => JSON.parse(JSON.stringify(x)); const h = ref<Hero | null>(p.edit ? clone(toPaper(p.edit)) : p.start === 'blank' ? blankPaper() : null); const from = ref(''), notes = ref<string[]>([]), text = ref(''), busy = ref(false), over = ref(false), scan = ref(''), scanB = ref<Uint8Array | null>(null); const file = ref<HTMLInputElement>()
const take = (b: Bring) => { h.value = b.hero; from.value = b.from; notes.value = b.notes }
const read = async (f: File) => { busy.value = true; try { const buf = new Uint8Array(await f.arrayBuffer()); if (/^image\//.test(f.type)) { h.value ??= blankPaper(); pin(f) } else if (buf[0] === 0x25 && buf[1] === 0x50) { const { readPdf } = await import('../pdf'); const r = await readPdf(buf); if (Object.keys(r.fields).length > 12) take(fromFields(r.fields)); else if (r.text.length > 60) take(fromText(r.text)); else { h.value = blankPaper(); notes.value = ['That PDF is only a picture, so nothing could be read from it. Fill in the form beside it.'] } } else { const t = new TextDecoder().decode(buf); let j: any = null; try { j = JSON.parse(t) } catch { /* words */ } if (j) { const r = fromJson(j); if (!r) throw new Error('That file holds no character I know how to read.'); if ('ours' in r) { const q = sanitize(r.ours); if (!q) throw new Error('That hero could not be read.'); keep(q); toast(`${q.name} has arrived.`); emit('done', q.id); return } take(r) } else take(fromText(t)) } } catch (e: any) { toast(e?.message ?? 'That file could not be read.', true) } finally { busy.value = false } }
const pick = (e: Event) => { const f = (e.target as HTMLInputElement).files?.[0]; if (f) void read(f) }; const drop = (e: DragEvent) => { over.value = false; const f = e.dataTransfer?.files[0]; if (f) void read(f) }; const paste = () => { if (text.value.trim().length < 20) { toast('Paste the whole sheet.', true); return } let j: any = null; try { j = JSON.parse(text.value) } catch { /* words */ } const r = j ? fromJson(j) : null; if (r && 'hero' in r) take(r); else take(fromText(text.value)) }
/** a photograph of the paper, kept beside the form */
function pin(f: File | null) { if (!f) { scan.value = ''; scanB.value = null; return } const u = URL.createObjectURL(f), im = new Image(); im.onload = () => { const k = Math.min(1, 1600 / Math.max(im.width, im.height)); const c = document.createElement('canvas'); c.width = im.width * k; c.height = im.height * k; c.getContext('2d')!.drawImage(im, 0, 0, c.width, c.height); scan.value = c.toDataURL('image/jpeg', .8); c.toBlob(async b => { if (b) scanB.value = new Uint8Array(await b.arrayBuffer()) }, 'image/jpeg', .8); URL.revokeObjectURL(u) }; im.onerror = () => { toast('That picture could not be opened.', true); URL.revokeObjectURL(u) }; im.src = u }
const sign = async () => { if (!h.value) return; if (!h.value.name.trim()) { toast('The sheet needs a name.', true); document.querySelector<HTMLInputElement>('.rec .big input')?.focus(); return } const q = sanitize(clone(settle(h.value))); if (!q) { toast('Something on the sheet cannot be read.', true); return } keep(q); if (scanB.value) await saveMap('hero:' + q.id, 'scan', scanB.value); choose(q.id); toast(`${q.name} is on record.`); emit('done', q.id) }
const back = () => { if (h.value && !p.edit && p.start !== 'blank') { h.value = null; notes.value = []; from.value = '' } else emit('done', '') }; void mine
</script>
<template><main class="br paper"><Bar :title="edit ? 'Amend the sheet' : h ? 'Record sheet' : 'Bring your own sheet'" :sub="from ? 'from ' + from : ''" @back="back"><button v-if="h" class="btn primary big" @click="sign">Sign the sheet</button></Bar><div class="bd scroll">
  <div v-if="!h" class="ch" :class="{ over }" @dragover.prevent="over = true" @dragleave="over = false" @drop.prevent="drop">
    <section><h2>Fill in a blank sheet</h2><p>Copy your paper sheet line by line. Your numbers are used as you write them: to hit, damage, saves, skills, hit points, slots. Leave a box empty and the rules fill it.</p><button class="btn primary big" @click="h = blankPaper()">Take a blank sheet</button></section>
    <section><h2>Hand over a file</h2><p>A fillable PDF (the official form, or one exported from D&amp;D Beyond), a JSON export from D&amp;D Beyond or Foundry, a text file, or a hero saved from this game. A photograph is pinned beside the blank sheet for you to copy from. Handwriting is not read.</p><button class="btn primary big" :disabled="busy" @click="file!.click()">{{ busy ? 'Reading…' : 'Choose a file' }}</button><span class="or">or drop it on this page</span><input ref="file" type="file" accept=".pdf,.json,.txt,.md,image/*" hidden @change="pick"></section>
    <section><h2>Paste the words</h2><p>From a character builder, a document, a chat. Scores, hit points, attacks, skills and spells are picked out by name.</p><textarea v-model="text" class="field" rows="8" aria-label="Paste the sheet" placeholder="Kessa Vane, Half-Elf Rogue 5&#10;AC 16  HP 33  Speed 30 ft&#10;STR 8 DEX 18 CON 12 …&#10;Rapier. +7 to hit, 1d8+4 piercing" /><button class="btn primary big" :disabled="!text.trim()" @click="paste">Read it</button></section></div>
  <template v-else><ul v-if="notes.length" class="notes"><li v-for="t in notes" :key="t">{{ t }}</li></ul><div class="in"><Record :h="h" :scan="scan" @scan="pin" /></div></template></div></main></template>
<style scoped>.br{position:fixed;inset:0;display:flex;flex-direction:column;z-index:5}.bd{flex:1;min-height:0}.ch{display:grid;grid-template-columns:repeat(3,1fr);min-height:100%}.ch.over{background:var(--spot)}section{padding:30px clamp(18px,3.2vw,48px) 40px;border-right:2px solid var(--ink)}section:last-child{border:0}section h2{font-size:34px;margin-bottom:12px}section p{max-width:44ch;margin-bottom:18px}.or{margin-left:14px;color:var(--ink2)}textarea{border:2px solid var(--ink)!important;margin-bottom:14px}.in{padding:24px clamp(18px,3.2vw,48px) 60px;max-width:1320px;margin:0 auto}.notes{margin:0;padding:12px clamp(18px,3.2vw,48px) 12px calc(clamp(18px,3.2vw,48px) + 18px);background:var(--spot);color:var(--on-spot)}@media(max-width:900px){.ch{grid-template-columns:1fr}section{border-right:0;border-bottom:2px solid var(--ink)}}</style>
